#include "../include/px4_comm_types.hpp"
#include <Eigen/Dense>
#include <gtest/gtest.h>
#include <iomanip>
#include <sstream>

using namespace px4_comm_types;

class Px4CommTypesTest : public ::testing::Test {
protected:
  void SetUp() override {
    // 创建测试数据
    test_time = rclcpp::Time(123456789, 987654321);
    test_translation = Eigen::Vector3d(1.0, 2.0, 3.0);
    test_quaternion = Eigen::Quaterniond::Identity();

    // 创建一个有效的测试位置
    valid_pos_enu = PositionENU(test_translation, test_quaternion, test_time);
    valid_pos_ned = PositionNED(test_translation, test_quaternion, test_time);
  }

  rclcpp::Time test_time;
  Eigen::Vector3d test_translation;
  Eigen::Quaterniond test_quaternion;
  PositionENU valid_pos_enu;
  PositionNED valid_pos_ned;
};

// 测试默认构造函数
TEST_F(Px4CommTypesTest, DefaultConstructor) {
  PositionENU pos_enu;
  PositionNED pos_ned;

  EXPECT_FALSE(pos_enu.valid);
  EXPECT_FALSE(pos_ned.valid);
  EXPECT_EQ(pos_enu.timestamp.nanoseconds(), 0);
  EXPECT_EQ(pos_ned.timestamp.nanoseconds(), 0);
}

// 测试参数构造函数
TEST_F(Px4CommTypesTest, ParameterConstructor) {
  EXPECT_TRUE(valid_pos_enu.valid);
  EXPECT_TRUE(valid_pos_ned.valid);
  EXPECT_EQ(valid_pos_enu.translation, test_translation);
  EXPECT_EQ(valid_pos_enu.orientation.coeffs(), test_quaternion.coeffs());
  EXPECT_EQ(valid_pos_enu.timestamp, test_time);
}

// 测试欧拉角转换
TEST_F(Px4CommTypesTest, EulerConversion) {
  // 测试单位四元数的欧拉角应该是零
  Eigen::Vector3d euler = valid_pos_enu.toEuler();
  EXPECT_NEAR(euler.x(), 0.0, 1e-10);
  EXPECT_NEAR(euler.y(), 0.0, 1e-10);
  EXPECT_NEAR(euler.z(), 0.0, 1e-10);

  // 测试绕Z轴旋转90度的情况
  Eigen::Quaterniond q_z90(
      Eigen::AngleAxisd(M_PI / 2, Eigen::Vector3d::UnitZ()));
  PositionENU pos_z90(test_translation, q_z90, test_time);
  Eigen::Vector3d euler_z90 = pos_z90.toEuler();
  EXPECT_NEAR(euler_z90.z(), M_PI / 2, 1e-6);
}

// 测试toString方法
TEST_F(Px4CommTypesTest, ToStringMethod) {
  std::string str = valid_pos_enu.toString();

  // 检查字符串包含关键信息
  EXPECT_TRUE(str.find("Position(valid=1") != std::string::npos);
  EXPECT_TRUE(str.find("1.000") != std::string::npos); // x坐标
  EXPECT_TRUE(str.find("2.000") != std::string::npos); // y坐标
  EXPECT_TRUE(str.find("3.000") != std::string::npos); // z坐标
  EXPECT_TRUE(str.find("q(w,x,y,z)=[1.000") !=
              std::string::npos); // 单位四元数w分量
}

// 测试坐标转换矩阵
TEST_F(Px4CommTypesTest, TransformationMatrix) {
  // 验证NED到ENU转换矩阵的性质
  Eigen::Matrix3d R_enu_from_ned = R_ned_from_enu.transpose();

  // 转换矩阵应该是正交矩阵
  Eigen::Matrix3d I = R_ned_from_enu * R_ned_from_enu.transpose();
  EXPECT_TRUE(I.isApprox(Eigen::Matrix3d::Identity(), 1e-10));

  // 行列式应该是1（保持右手坐标系）
  EXPECT_NEAR(R_ned_from_enu.determinant(), 1.0, 1e-10);
}

// 测试ENU到NED转换
TEST_F(Px4CommTypesTest, EnuToNedConversion) {
  // 测试有效位置的转换
  PositionNED pos_ned = enuToNed(valid_pos_enu);

  EXPECT_TRUE(pos_ned.valid);
  EXPECT_EQ(pos_ned.timestamp, valid_pos_enu.timestamp);

  // 验证坐标转换的正确性
  Eigen::Vector3d expected_translation =
      R_ned_from_enu * valid_pos_enu.translation;
  EXPECT_TRUE(pos_ned.translation.isApprox(expected_translation, 1e-10));

  // 测试无效位置的转换
  PositionENU invalid_pos;
  PositionNED result = enuToNed(invalid_pos);
  EXPECT_FALSE(result.valid);
}

// 测试NED到ENU转换
TEST_F(Px4CommTypesTest, NedToEnuConversion) {
  // 测试有效位置的转换
  PositionENU pos_enu = nedToEnu(valid_pos_ned);

  EXPECT_TRUE(pos_enu.valid);
  EXPECT_EQ(pos_enu.timestamp, valid_pos_ned.timestamp);

  // 验证坐标转换的正确性
  Eigen::Vector3d expected_translation =
      R_ned_from_enu.transpose() * valid_pos_ned.translation;
  EXPECT_TRUE(pos_enu.translation.isApprox(expected_translation, 1e-10));

  // 测试无效位置的转换
  PositionNED invalid_pos;
  PositionENU result = nedToEnu(invalid_pos);
  EXPECT_FALSE(result.valid);
}

// 测试双向转换的一致性
TEST_F(Px4CommTypesTest, BidirectionalConversion) {
  // ENU -> NED -> ENU 应该得到原始值
  PositionNED ned_from_enu = enuToNed(valid_pos_enu);
  PositionENU enu_back = nedToEnu(ned_from_enu);

  EXPECT_TRUE(enu_back.valid);
  EXPECT_TRUE(enu_back.translation.isApprox(valid_pos_enu.translation, 1e-10));
  EXPECT_TRUE(enu_back.orientation.coeffs().isApprox(
      valid_pos_enu.orientation.coeffs(), 1e-10));
  EXPECT_EQ(enu_back.timestamp, valid_pos_enu.timestamp);

  // NED -> ENU -> NED 应该得到原始值
  PositionENU enu_from_ned = nedToEnu(valid_pos_ned);
  PositionNED ned_back = enuToNed(enu_from_ned);

  EXPECT_TRUE(ned_back.valid);
  EXPECT_TRUE(ned_back.translation.isApprox(valid_pos_ned.translation, 1e-10));
  EXPECT_TRUE(ned_back.orientation.coeffs().isApprox(
      valid_pos_ned.orientation.coeffs(), 1e-10));
  EXPECT_EQ(ned_back.timestamp, valid_pos_ned.timestamp);
}

// 测试特殊情况：坐标轴对齐
TEST_F(Px4CommTypesTest, AxisAlignedConversions) {
  // 测试各坐标轴的单位向量转换
  std::vector<Eigen::Vector3d> enu_axes = {
      Eigen::Vector3d::UnitX(), // 东
      Eigen::Vector3d::UnitY(), // 北
      Eigen::Vector3d::UnitZ()  // 上
  };

  std::vector<Eigen::Vector3d> expected_ned = {
      Eigen::Vector3d::UnitY(), // 东 -> 北
      Eigen::Vector3d::UnitX(), // 北 -> 东
      -Eigen::Vector3d::UnitZ() // 上 -> 下
  };

  for (size_t i = 0; i < enu_axes.size(); ++i) {
    PositionENU pos_enu(enu_axes[i], Eigen::Quaterniond::Identity(), test_time);
    PositionNED pos_ned = enuToNed(pos_enu);

    EXPECT_TRUE(pos_ned.translation.isApprox(expected_ned[i], 1e-10))
        << "Axis " << i << " conversion failed";
  }
}

// 测试四元数归一化
TEST_F(Px4CommTypesTest, QuaternionNormalization) {
  // 创建一个非归一化的四元数
  Eigen::Quaterniond q_unnormalized(2.0, 0.0, 0.0, 0.0);
  PositionENU pos_enu(test_translation, q_unnormalized, test_time);

  // 转换后四元数应该仍然是归一化的
  PositionNED pos_ned = enuToNed(pos_enu);
  EXPECT_NEAR(pos_ned.orientation.norm(), 1.0, 1e-10);
}

// 性能测试：批量转换
TEST_F(Px4CommTypesTest, BatchConversionPerformance) {
  const int NUM_CONVERSIONS = 10000;
  std::vector<PositionENU> enu_positions;
  std::vector<PositionNED> ned_positions;

  // 准备测试数据
  for (int i = 0; i < NUM_CONVERSIONS; ++i) {
    Eigen::Vector3d t(i * 0.1, i * 0.2, i * 0.3);
    Eigen::Quaterniond q = Eigen::Quaterniond::Identity();
    enu_positions.emplace_back(t, q, test_time);
  }

  // 测量转换时间
  auto start = std::chrono::high_resolution_clock::now();
  for (const auto &pos : enu_positions) {
    ned_positions.push_back(enuToNed(pos));
  }
  auto end = std::chrono::high_resolution_clock::now();

  auto duration =
      std::chrono::duration_cast<std::chrono::microseconds>(end - start);

  // 验证所有转换都成功
  EXPECT_EQ(ned_positions.size(), NUM_CONVERSIONS);
  for (const auto &pos : ned_positions) {
    EXPECT_TRUE(pos.valid);
  }

  // 输出性能信息（可选）
  std::cout << "Converted " << NUM_CONVERSIONS << " positions in "
            << duration.count() << " microseconds\n";
}

int main(int argc, char **argv) {
  ::testing::InitGoogleTest(&argc, argv);
  return RUN_ALL_TESTS();
}
